from pathlib import Path
import shutil

ROOT = Path(__file__).resolve().parent
REPO = ROOT.parent.parent
ASSETS = ROOT / 'assets'
for name, source in {
    'workspace.png': 'src/AkmlSql.Site/wwwroot/img/screenshots/query-results.png',
    'completion.png': 'src/AkmlSql.Site/wwwroot/img/screenshots/light/05-join-suggestions-crop.png',
    'styles.png': 'src/AkmlSql.Site/wwwroot/img/screenshots/dark/02-format-styles-crop.png',
    'history.png': 'src/AkmlSql.Site/wwwroot/img/screenshots/dark/01-sql-history-crop.png',
}.items():
    shutil.copy2(REPO / source, ASSETS / name)

def write(name, text):
    (ROOT / name).write_text(text, encoding='utf-8')

